  document.getElementById('local-danmu-episode-label').textContent = isMovie ? '\u96C6\uFF08\u53EF\u9009\uFF09' : '\u96C6';
  season.placeholder = isMovie ? '\u53EF\u4E0D\u586B' : '\u9ED8\u8BA4 1';
